<?php
declare(strict_types=1);
$base='/var/www/html/network-scanner';
$scanFile="$base/data/scan_output.txt";$historyFile="$base/data/scan_history.csv";$logFile="$base/data/scan_errors.log";
$error=null;$hosts=[];$history=[];$target='Unknown';$scannerHost='Unknown';$command=null;$scanStart=null;$scanEnd=null;$duration=null;$scanAge=null;$successful=false;
$totalUp=0;$open=0;$high=0;$medium=0;$review=0;$info=0;$attempts=0;$successes=0;$failures=0;$successRate=0;$lastActivity=null;$lastError=null;$stale=900;$status='OFFLINE';
$risky=[21=>['HIGH','FTP may transmit credentials without encryption.'],23=>['HIGH','Unencrypted remote administration protocol.'],25=>['MEDIUM','Mail service should be securely configured.'],135=>['MEDIUM','Windows RPC service exposed to the network.'],139=>['MEDIUM','Legacy Windows networking service.'],445=>['HIGH','SMB exposure can increase lateral-movement risk.'],1433=>['MEDIUM','Database service exposed directly to the network.'],3306=>['MEDIUM','Database service exposed directly to the network.'],3389=>['HIGH','Remote Desktop should not be unnecessarily exposed.'],5900=>['HIGH','Remote desktop service exposed to the network.']];
function h(?string $s):string{return htmlspecialchars($s??'',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function dur(?int $s):string{if($s===null)return'Unknown';if($s<60)return$s.'s';return intdiv($s,60).'m '.($s%60).'s';}
function age(?int $s):string{if($s===null)return'Unknown';if($s<60)return'less than a minute ago';$m=intdiv($s,60);if($m<60)return$m.' minute'.($m===1?'':'s').' ago';$hr=intdiv($m,60);return$hr.'h '.($m%60).'m ago';}
function parseNmap(string $c):array{$out=[];$cur=null;$lines=preg_split('/\r\n|\r|\n/',$c)?:[];foreach($lines as $line){$line=trim($line);if($line===''||str_starts_with($line,'#'))continue;if(preg_match('/^Nmap scan report for\s+(.+)$/',$line,$m)){ $cur=trim($m[1]);$out[$cur]??=[];continue;}if($cur!==null&&preg_match('/^(\d+)\/(tcp|udp)\s+open\s+(\S+)(?:\s+(.*))?$/',$line,$m))$out[$cur][]= ['port'=>(int)$m[1],'protocol'=>$m[2],'service'=>$m[3],'version'=>trim($m[4]??'')];}return$out;}
function classify(array $p):array{global$risky;$n=(int)$p['port'];$s=strtolower((string)$p['service']);if(isset($risky[$n]))return['level'=>$risky[$n][0],'note'=>$risky[$n][1]];if($s==='unknown'||$s==='tcpwrapped'||str_contains($s,'?'))return['level'=>'REVIEW','note'=>'Nmap could not confidently identify this service.'];if($n===53)return['level'=>'REVIEW','note'=>'DNS service detected. Review exposure based on network role.'];if($n===80)return['level'=>'REVIEW','note'=>'HTTP service detected. Review whether unencrypted HTTP is required.'];if($n===443)return['level'=>'INFO','note'=>'HTTPS service detected.'];return['level'=>'INFO','note'=>'Recognised service detected.'];}
if(is_readable($historyFile)&&($fh=fopen($historyFile,'r'))!==false){fgetcsv($fh);while(($r=fgetcsv($fh))!==false){if(count($r)<6)continue;$st=strtoupper(trim((string)$r[1]));$history[]=['timestamp'=>$r[0],'status'=>$st,'ips'=>$r[2],'up'=>$r[3],'duration'=>$r[4],'message'=>$r[5]];$attempts++;if($st==='SUCCESS')$successes++;elseif($st==='FAILED')$failures++;}fclose($fh);if($attempts)$successRate=round($successes/$attempts*100,1);$history=array_slice(array_reverse($history),0,10);}
if(!is_readable($scanFile))$error='Scan output is unavailable.';else{$c=file_get_contents($scanFile);if($c===false||trim($c)==='')$error='Scan output is empty.';else{$hosts=parseNmap($c);if(preg_match('/Nmap done:\s+(\d+)\s+IP addresses\s+\((\d+)\s+hosts? up\)/',$c,$m)){$scanned=(int)$m[1];$totalUp=(int)$m[2];}else$scanned=0;if(preg_match('/# Target range:\s*(.+)/',$c,$m))$target=trim($m[1]);if(preg_match('/# Scanner host:\s*(.+)/',$c,$m))$scannerHost=trim($m[1]);if(preg_match('/# Scanner command:\s*(.+)/',$c,$m))$command=trim($m[1]);if(preg_match('/# Scan started:\s*(.+)/',$c,$m))$scanStart=trim($m[1]);if(preg_match('/# Scan completed:\s*(.+)/',$c,$m))$scanEnd=trim($m[1]);$successful=$scanEnd!==null&&preg_match('/Nmap done:\s+[1-9][0-9]*\s+IP addresses\s+\([0-9]+\s+hosts? up\)/',$c)===1;if($scanStart&&$scanEnd){$a=strtotime($scanStart);$b=strtotime($scanEnd);if($a!==false&&$b!==false&&$b>=$a)$duration=$b-$a;}if($successful&&$scanEnd){$e=strtotime($scanEnd);if($e!==false)$scanAge=max(0,time()-$e);}foreach($hosts as $ps)foreach($ps as $p){$open++;$cl=classify($p);if($cl['level']==='HIGH')$high++;elseif($cl['level']==='MEDIUM')$medium++;elseif($cl['level']==='REVIEW')$review++;else$info++;}}}
if(is_readable($logFile)&&($lc=file_get_contents($logFile))!==false&&trim($lc)!==''){$ls=preg_split('/\r\n|\r|\n/',trim($lc))?:[];for($i=count($ls)-1;$i>=0;$i--){$line=trim($ls[$i]);if(preg_match('/^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) - (.+)$/',$line,$m)){$lastActivity=$m[1];break;}}for($i=count($ls)-1;$i>=0;$i--){$line=trim($ls[$i]);if(str_contains($line,'ERROR:')||str_contains($line,'WARNING:')){$lastError=$line;break;}}}
if($error===null&&$successful&&$scanAge!==null)$status=$scanAge<=$stale?'ONLINE':'STALE';
if($status==='ONLINE'){$diagnostic='Scanner is operating normally and recent scan data is available.';$statusMsg='Last successful scan was '.age($scanAge).'.';}elseif($status==='STALE'){$diagnostic='The last successful scan is older than the configured threshold.';$statusMsg='Last successful scan was '.age($scanAge).'.';}else{$diagnostic=$lastError!==null?'No valid successful scan is currently available. Check the scanner diagnostics below.':'No successful scan information is available.';$statusMsg='No valid successful scan is available.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="30"><title>Network Scanner Dashboard</title><style>
:root{--bg:#f4f7fb;--card:#fff;--text:#172033;--muted:#64748b;--border:#e2e8f0;--blue:#2563eb;--green:#16a34a;--yellow:#d97706;--red:#dc2626;--purple:#7c3aed}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--bg);color:var(--text)}header{background:linear-gradient(135deg,#0f172a,#1e3a8a);color:#fff;padding:32px 20px}.wrap,main,footer{max-width:1250px;margin:auto}.head{display:flex;justify-content:space-between;gap:20px;align-items:center}h1{margin:0 0 7px;font-size:clamp(1.6rem,4vw,2.3rem)}.sub{margin:0;opacity:.82;font-size:.95rem}.meta{text-align:right;font-size:.82rem;opacity:.9}main{padding:26px 20px 45px}.card{background:var(--card);border:1px solid var(--border);border-radius:16px;box-shadow:0 10px 30px rgba(15,23,42,.07)}.health{padding:22px;margin-bottom:22px}.healthhead{display:flex;justify-content:space-between;gap:20px}.title{margin:0 0 5px;font-size:1.2rem}.muted{color:var(--muted);font-size:.88rem}.badge,.smallbadge,.level{display:inline-block;border-radius:999px;font-weight:800}.badge{padding:8px 13px;font-size:.78rem}.online{background:#f0fdf4;color:var(--green)}.stale{background:#fffbeb;color:var(--yellow)}.offline{background:#fef2f2;color:var(--red)}.diag{margin-top:18px;padding:14px 16px;background:#f8fafc;border-left:4px solid var(--blue);border-radius:8px}.label{font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin-bottom:5px}.err{color:var(--red);font-size:.8rem;margin-top:7px;word-break:break-word}.grid{display:grid;gap:18px}.stats{grid-template-columns:repeat(4,1fr);margin-bottom:22px}.stat,.info{padding:20px}.value{font-size:2rem;font-weight:850;margin:6px 0 2px}.desc{color:var(--muted);font-size:.78rem}.green{color:var(--green)}.red{color:var(--red)}.yellow{color:var(--yellow)}.blue{color:var(--blue)}.infos{grid-template-columns:repeat(4,1fr);margin-bottom:22px}.section{padding:22px;margin-bottom:22px}.tablewrap{overflow-x:auto;margin-top:15px}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:12px 10px;text-align:left;border-bottom:1px solid var(--border);font-size:.82rem;vertical-align:top}th{color:var(--muted);font-size:.7rem;text-transform:uppercase;letter-spacing:.05em}.host{border:1px solid var(--border);border-radius:12px;overflow:hidden;margin-top:14px}.hosthead{padding:13px 15px;background:#f8fafc;display:flex;justify-content:space-between;gap:12px}.hostname{font-weight:800;word-break:break-all}.smallbadge{padding:4px 8px;font-size:.68rem}.ok{background:#f0fdf4;color:var(--green)}.bad{background:#fef2f2;color:var(--red)}.level{padding:4px 8px;font-size:.68rem}.high{background:#fef2f2;color:var(--red)}.med{background:#fffbeb;color:var(--yellow)}.rev{background:#f3e8ff;color:var(--purple)}.inf{background:#eff6ff;color:var(--blue)}.empty{padding:30px;text-align:center;color:var(--muted)}.alert{padding:15px 18px;background:#fef2f2;color:#991b1b;border:1px solid #fecaca;border-radius:10px;margin-bottom:20px}footer{padding:0 20px 30px;color:var(--muted);text-align:center;font-size:.76rem}@media(max-width:950px){.stats,.infos{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.head,.healthhead{flex-direction:column}.meta{text-align:left}main{padding:18px 12px 35px}.stats,.infos{grid-template-columns:1fr}header{padding:24px 14px}}
</style></head><body><header><div class="wrap head"><div><h1>Network Scanner Dashboard</h1><p class="sub">Nmap-based network discovery, service monitoring and security review</p></div><div class="meta">Auto-refresh: 30 seconds<br>Scanner host: <?=h($scannerHost)?></div></div></header><main>
<?php if($error!==null):?><div class="alert"><?=h($error)?></div><?php endif;?>
<section class="card health"><div class="healthhead"><div><h2 class="title">Scanner Health</h2><div class="muted"><?=h($statusMsg)?></div></div><span class="badge <?=$status==='ONLINE'?'online':($status==='STALE'?'stale':'offline')?>">● <?=$status?></span></div><div class="diag"><div class="label">Scanner Diagnostics</div><div><?=h($diagnostic)?></div><?php if($lastActivity):?><div class="muted" style="margin-top:6px">Last scanner activity: <?=h($lastActivity)?></div><?php endif;?><?php if($lastError):?><div class="err"><?=h($lastError)?></div><?php endif;?></div></section>
<section class="grid stats"><div class="card stat"><div class="label">Hosts Up</div><div class="value green"><?=$totalUp?></div><div class="desc">Devices responding to Nmap</div></div><div class="card stat"><div class="label">Hosts With Open Ports</div><div class="value blue"><?=count($hosts)?></div><div class="desc">Devices exposing services</div></div><div class="card stat"><div class="label">Open Ports</div><div class="value"><?=$open?></div><div class="desc">Services exposed</div></div><div class="card stat"><div class="label">High Risk</div><div class="value red"><?=$high?></div><div class="desc">Ports requiring attention</div></div><div class="card stat"><div class="label">Medium Risk</div><div class="value yellow"><?=$medium?></div><div class="desc">Ports to review</div></div><div class="card stat"><div class="label">Review</div><div class="value"><?=$review?></div><div class="desc">Services requiring context</div></div><div class="card stat"><div class="label">Informational</div><div class="value blue"><?=$info?></div><div class="desc">Recognised services</div></div><div class="card stat"><div class="label">Success Rate</div><div class="value green"><?=h((string)$successRate)?>%</div><div class="desc"><?=$successes?> successful / <?=$attempts?> attempts</div></div></section>
<section class="grid infos"><div class="card info"><div class="label">Target Network</div><div><strong><?=h($target)?></strong></div></div><div class="card info"><div class="label">Last Successful Scan</div><div><strong><?=h($scanEnd??'Unknown')?></strong></div></div><div class="card info"><div class="label">Scan Duration</div><div><strong><?=h(dur($duration))?></strong></div></div><div class="card info"><div class="label">Last Scan Activity</div><div><strong><?=h($lastActivity??'Unknown')?></strong></div></div></section>
<section class="card section"><h2 class="title">Discovered Hosts & Services</h2><div class="muted">Open TCP/UDP services from the latest validated scan</div><?php if(!$hosts):?><div class="empty">No hosts with open ports were discovered.</div><?php else:?><div><?php foreach($hosts as $host=>$ports):?><div class="host"><div class="hosthead"><div class="hostname"><?=h($host)?></div><div><?=count($ports)?> open port<?=count($ports)===1?'':'s'?></div></div><div class="tablewrap"><table><thead><tr><th>Port</th><th>Protocol</th><th>Service</th><th>Version</th><th>Classification</th><th>Note</th></tr></thead><tbody><?php foreach($ports as $p):$cl=classify($p);$cc=$cl['level']==='HIGH'?'high':($cl['level']==='MEDIUM'?'med':($cl['level']==='REVIEW'?'rev':'inf'));?><tr><td><strong><?=intval($p['port'])?></strong></td><td><?=h($p['protocol'])?></td><td><?=h($p['service'])?></td><td><?=h($p['version']?:'—')?></td><td><span class="level <?=$cc?>"><?=h($cl['level'])?></span></td><td><?=h($cl['note'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php endforeach;?></div><?php endif;?></section>
<section class="card section"><h2 class="title">Scanner History</h2><div class="muted">Latest 10 attempts; failures are retained for diagnostics</div><?php if(!$history):?><div class="empty">No scan history is available.</div><?php else:?><div class="tablewrap"><table><thead><tr><th>Time</th><th>Status</th><th>IPs Scanned</th><th>Hosts Up</th><th>Duration</th><th>Result</th></tr></thead><tbody><?php foreach($history as $r):$ok=$r['status']==='SUCCESS';?><tr><td><?=h($r['timestamp'])?></td><td><span class="smallbadge <?=$ok?'ok':'bad'?>">● <?=$ok?'SUCCESS':'FAILED'?></span></td><td><?=h($r['ips'])?></td><td><?=h($r['up'])?></td><td><?=h($r['duration'])?>s</td><td><?=h($r['message'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="card info" style="margin-bottom:22px"><div class="label">Scanner Command</div><div style="font-family:ui-monospace,monospace;font-size:.82rem;word-break:break-all"><?=h($command??'Unavailable')?></div></section></main><footer>Network Scanner Dashboard • Linux • Nmap • PHP • Automated scan history and scanner health monitoring</footer></body></html>
